\mathbf{E}(1)=\sum_j\frac{1}{4\pi\epsilon_0}\,\frac{q_j}{r_{1j}^2}\,\mathbf{e}_{1j}.

\end{equation}

Which means, of course,

\begin{equation}

\label{Eq:II:4:14}

E_x(x_1,y_1,z_1)=\sum_j\frac{1}{4\pi\epsilon_0}\,

\frac{q_j(x_1-x_j)}{[(x_1-x_j)^2+(y_1-y_j)^2+(z_1-z_j)^2]^{3/2}},

\end{equation}

\begin{align}

\label{Eq:II:4:14}

E_x&(x_1,y_1,z_1)=\\[.5ex]

