\label{Eq:II:7:13}

F(z)=z^{2/3},

\end{equation}

which yields the field outside a rectangular corner

\begin{equation}

\label{Eq:II:7:14}

F(z)=\lnz,

\end{equation}

which yields the field for a line charge, and

\begin{equation}

