\label{Eq:II:32:15}

\nabla \cdot \mathbf{D}=\rho_{\text{other}}

\end{equation}

and

\begin{equation}

\label{Eq:II:32:16}

\epsilon_0 c^2\nabla \times \mathbf{B}=\mathbf{j}_{\text{other}}+\frac{\partial \mathbf{D}}{\partial t}.

\end{equation}

