(\text{b}) &

c^2\nabla \times \mathbf{B}=\displaystyle\frac{\partial}{\partial t}\biggl(\dfrac{\mathbf{P}}{\epsilon_0}+

\mathbf{E}\biggr)\\

\\

(\text{c}) &

\nabla \times \mathbf{E}=-\displaystyle\frac{\partial \mathbf{B}}{\partial t} &

(\text{d}) &

\nabla \cdot \mathbf{B}=0

\end{array}

\end{equation}

\begin{equation}

\begin{aligned}

&(\text{a})\;\;\nabla \cdot \mathbf{E}=-\dfrac{\nabla \cdot \mathbf{P}}{\epsilon_0}\\[1ex]

&(\text{b})\;\;c^2\nabla \times \mathbf{B}=\displaystyle\frac{\partial}{\partial t}\biggl(\dfrac{\mathbf{P}}{\epsilon_0}+\mathbf{E}\biggr)\\[1ex]

&(\text{c})\;\;\nabla \times \mathbf{E}=-\displaystyle\frac{\partial \mathbf{B}}{\partial t}\\[1.5ex]

&(\text{d})\;\;\nabla \cdot \mathbf{B}=0

\end{aligned}

\label{Eq:II:32:19}

\end{equation}

We can solve these equations as we have done before. We start by

taking the curl of Eq. ( 32.19 c):

\begin{equation*}

\nabla \times (\FLPcurl{\mathbf{E})}=-\frac{\partial}{\partial t}\,\nabla \times \mathbf{B}.

\end{equation*}

Next, we make use of the vector identity

\begin{equation*}

\nabla \times (\FLPcurl{\mathbf{E})}=\nabla (\nabla \cdot \mathbf{E})-\nabla^2\mathbf{E},

\end{equation*}

and also substitute for $\nabla \times \mathbf{B}$, using

Eq. ( 32.19 b); we get

\begin{equation*}

\nabla (\nabla \cdot \mathbf{E})-\nabla^2\mathbf{E}=

-\frac{1}{\epsilon_0 c^2}\,\frac{\partial^2\mathbf{P}}{\partial t^2}-

\frac{1}{c^2}\,\frac{\partial^2\mathbf{E}}{\partial t^2}.

\end{equation*}

Using Eq. ( 32.19 a) for $\nabla \cdot \mathbf{E}$, we get

\begin{equation}

\label{Eq:II:32:20}

\nabla^2\mathbf{E}-\frac{1}{c^2}\,\frac{\partial^2\mathbf{E}}{\partial t^2}=

-\frac{1}{\epsilon_0}\,\nabla (\nabla \cdot \mathbf{P})+

\frac{1}{\epsilon_0 c^2}\,\frac{\partial^2\mathbf{P}}{\partial t^2}.

\end{equation}

\begin{align}

\label{Eq:II:32:20}

\nabla^2\mathbf{E}&-\frac{1}{c^2}\,\frac{\partial^2\mathbf{E}}{\partial t^2}=\\[1ex]

&-\frac{1}{\epsilon_0}\,\nabla (\nabla \cdot \mathbf{P})+

\frac{1}{\epsilon_0 c^2}\,\frac{\partial^2\mathbf{P}}{\partial t^2}.\notag

\end{align}

So instead of the wave equation, we now get that the d’Alembertian

