C_{xxyy}&=\frac{Y}{1+\sigma}

\biggl(\frac{\sigma}{1-2\sigma}\biggr),\\[.5ex]

C_{xyxy}&=\frac{Y}{2(1+\sigma)}.

\end{aligned}

\label{Eq:II:39:22}

\end{equation}

